import {operationCounts} from './brain-cost.js';
import {LEARNING_RULES,FEELING_SCALES} from './brain-input-scales.js';
import {DECISION_COST,REPEAT_COST} from './action-timing.js';
import {v,p,a,table,details} from './guide-markup.js';

/** Учебная ситуация: семь клеток и все виды кандидатов. Работает счётчик модели. */
export const guideReferenceOperations=()=>operationCounts(null,7,11,6);
const reference=guideReferenceOperations();
export const GUIDE_LEARNING_TEXT={
 'guide-learning-body':
 p('Личное обучение меняет добавки к весам мозга по опыту одного жителя. Наследуемые исходные веса при этом сохраняются. Действующая схема использует ожидаемую оценку следующего выбора и градиентный след: изменение может затронуть не только последнее действие, но и параметры, участвовавшие в более ранних оценках.')
 +'<h4>Один переход обучения</h4><ol>'
 +'<li>После принятия действия сохраняются его входы, исходное самочувствие и начало перехода. Это личная запись, которой нет в геноме.</li>'
 +'<li>Во время процесса накапливается субъективное подкрепление с учётом прошедшего времени и дисконтирования. Поэтому длительный процесс не сводится к разнице двух мгновенных ощущений.</li>'
 +'<li>Перед следующим основным выбором вычисляется ожидаемая Q по доступным кандидатам и их вероятностям. Предыдущий прогноз сравнивается с накопленным результатом и этим продолжением.</li>'
 +'<li>Ошибка и след градиентов меняют личные поправки. Затем новый выбор уже использует обновлённые действующие веса.</li></ol>'
 +'<h4>Пример: ожидали меньше, чем получили</h4>'
 +p('Если субъективный результат вместе с ожидаемым продолжением оказался выше прежней Q, ошибка положительна. Поправки идут вдоль градиентного следа; конкретный вес может как вырасти, так и уменьшиться в зависимости от знака градиента. Это не универсальная команда повысить все веса выбранного действия. При следующем выборе сравнение с другими кандидатами заново определит вероятности.')
 +table('Что хранится отдельно',['Состояние','За жизнь','У ребёнка'],[
 ['Генетическая основа сети','Служит исходными весами.','Копируется и может мутировать.'],
 ['Личные поправки','Меняются обучением и затухают.','Начинаются нулевыми.'],
 ['Градиентные следы и ожидающий переход','Связывают прошлые оценки с результатом.','Создаются заново.'],
 ['Пространственная память','Обновляется наблюдениями и переживаниями.','Начинается пустой.']])
 +details('Параметры, ограничения и время',
 p('Скорость обучения масштабирует обновление. Дисконт уменьшает вес будущего с учётом длительности перехода. Параметр следа определяет сохранность влияния предыдущих градиентов. Забывание уменьшает личные поправки по прошедшему времени перед новым решением, не переписывая наследуемую основу.')
 +p(`Для численной устойчивости градиент нормируется, ошибка ограничивается по модулю ${v(LEARNING_RULES.tdErrorLimit)}, личная поправка — по модулю ${v(LEARNING_RULES.weightDeltaLimit)}. Эти границы относятся к обучению, а не к вероятности действия или запасу энергии. Ощущения нормируются своей шкалой ${v(FEELING_SCALES.maximum)}.`)
 +p('У текущего мозга обучаются кодировщик клеток, контекст, проекции и прямая оценка. Структура связей в течение жизни неизменна, а малая сеть вызова не обучается. Запись памяти и усиление значимости могут происходить при выключенном обучении весов: это разные механизмы.'))
 +details('Выключение обучения, прерывание и гибель',
 p('При выключенном обучении оценки используют наследуемые веса без личных поправок, а обновление весов не выполняется. Оно не отключает наблюдения и пространственную память. При добровольной смене процесса накопленный живым жителем переход разбирается перед новым решением; смена действия не стирает уже пережитое время.')
 +p('При гибели ожидающий переход очищается без завершающего обучения мёртвого организма. По этой причине нельзя переносить сюда описание другого алгоритма с обязательной терминальной поправкой. Полный мир сохраняет личные веса, следы и незавершённые переходы; отдельный геном — только наследуемую основу.'))
 +p(`Связанные темы: ${a('feelings','подкрепление и чувствительности')}, ${a('choice','ожидаемый следующий выбор')}, ${a('brain-cost','цена обучения')}, ${a('genome','наследование')}.`),

 'guide-brain-cost-body':
 p('Мышление оплачивается энергией по детерминированному счётчику условных операций. Он оценивает работу сети по структуре и числу рассматриваемых данных, а не измеряет миллисекунды процессора. Один и тот же мозг имеет одинаковую физическую цену на быстром и медленном компьютере.')
 +p(`Базовые ставки ${v(DECISION_COST)} и ${v(REPEAT_COST,'энергии')} откалиброваны на полный эталонный цикл выбора с обучением. Фактический выбор оплачивает свою долю операций, а выполненное обучение — отдельную долю. Нельзя начислять полную базовую ставку каждой фазе: это удвоило бы цену.`)
 +'<h4>Пример: эталонный счётчик</h4>'
 +table('Учебный набор: семь клеток, все одиннадцать кандидатов и шесть операций',['Фаза эталона','Условных операций'],[
 ['Прямой выбор',v(reference.forward)],['Обучение и связанные вычисления',v(reference.learning)]])
 +p('Для изменяемой схемы вместо эталонного контекста подставляется её собственный счётчик. Общие вычисления клеток и ситуации выполняются на пакет выбора, а не заново для каждого кандидата. Поэтому удвоение одних скрытых нейронов не обязано удвоить цену всего мозга: фиксированные части и состав кандидатов тоже вносят вклад.')
 +details('Что включается в цену',
 p('Умножение со сложением учитывается как две условные операции; tanh, смещение и скалярная работа имеют принятые веса счётчика. В обучении учитываются следующее оценивание, градиент прежнего перехода, нормировка/изменение параметров и контрольная оценка после обновления. Это модель стоимости, а не профиль аппаратных инструкций CPU. Отдельная цена проверки малой сети вызова не начисляется: учёт относится к основному мозгу.')
 +p('Для DAG учитываются связи и узлы, структурно участвующие в пути к выходам. Нулевой вес существующей связи не делает её отсутствующей. Ветвь без пути к выходу может быть пропущена планом вычисления. Даже без скрытых нейронов остаются выходы, кодировщик и другие фиксированные части, поэтому нулевое число скрытых нейронов не означает бесплатный мозг.')
 +p('Если обучение выключено или нового завершённого живого перехода ещё нет, соответствующая дополнительная работа не оплачивается. Нулевая скорость обучения сама по себе не обещает отсутствия вычислений: выполненную фазу нужно отличать от величины изменения весов.'))
 +details('Оплата, дефицит и график',
 p('Цена выбора и выполненного обучения суммируется при принятии решения. Списывается доступная энергия; её нехватка уменьшает здоровье по физике дефицита. Смертельная оплата не запускает действие. Ставка повторения относится к повторному процессу после завершения, а не к каждому подшагу продолжения.')
 +p('В наблюдениях отдельно записывается запрошенная стоимость вычислений; энергетический расход отражает фактически списанную энергию. Нельзя приравнивать эти ряды при дефиците. Средняя стоимость вызова использует число вызовов как знаменатель; малое значение может округляться, а отсутствие вызовов — отдельный случай. Настоящие времена расчёта и ожидания относятся к измерениям производительности.'))
 +p(`Связанные темы: ${a('learning','фазы обучения')}, ${a('energy','оплата здоровьем')}, ${a('choice','продолжение и повтор')}, ${a('research','численные показатели')}.`),
};
